"""
Cleanup functions: turn the different spellings of the same key into one.

Pure functions only. No values from the portal data live here; supplier ids are learned from the
supplier profiles at runtime.
"""

import re
from datetime import date, datetime

_LIST_SEP = re.compile(r"\s*[|,;]\s*")
_NON_ALNUM = re.compile(r"[^0-9a-z]+")


def is_blank(value) -> bool:
    if value is None:
        return True
    if isinstance(value, float) and value != value:  # NaN
        return True
    return isinstance(value, str) and not value.strip()


def clean(value) -> str | None:
    """Strip a value to a string, or None when it is empty or missing."""
    return None if is_blank(value) else str(value).strip()


def split_list(value) -> list[str]:
    """Split a joined list such as 'a|b' or 'a, b' into its parts."""
    text = clean(value)
    if text is None:
        return []
    return [part for part in _LIST_SEP.split(text) if part]


def po_line(value) -> str | None:
    """
    Bring PO line numbers to one form.

    SAP item numbers are zero-padded and count in steps of ten ('00010' is line 1, '00510' is
    line 51). Plain numbers ('1') are taken as they are.
    """
    text = clean(value)
    if text is None or not text.isdigit():
        return text
    number = int(text)
    if len(text) >= 5 and text.startswith("0") and number % 10 == 0:
        return str(number // 10)
    return str(number)


def parse_number(value, decimal_comma: bool = False) -> float | None:
    """Parse '1,5200' (decimal comma) or '44,000' (thousands comma). None when unparseable."""
    text = clean(value)
    if text is None:
        return None
    text = text.replace(" ", "").replace(" ", "")
    if decimal_comma:
        text = text.replace(".", "").replace(",", ".")
    else:
        text = text.replace(",", "")
    try:
        return float(text)
    except ValueError:
        return None


def parse_date(value, formats: tuple[str, ...] = ("%Y-%m-%d",)) -> str | None:
    """Return an ISO date (YYYY-MM-DD), or None when the value matches none of the formats."""
    if isinstance(value, datetime):
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()
    text = clean(value)
    if text is None:
        return None
    for fmt in formats:
        try:
            return datetime.strptime(text, fmt).date().isoformat()
        except ValueError:
            continue
    return None


def name_key(value) -> str:
    """Comparable form of a name: lower case, letters and digits only."""
    return _NON_ALNUM.sub("", str(value).lower())


class SupplierResolver:
    """
    Maps every way the data names a supplier to one supplier id.

    Learned from the supplier profiles: the id itself ('SUP-0019'), its number ('19'), the name,
    the legal name and the portal folder name ('SUP-0019_Dongguan_Precision_Housings').
    """

    def __init__(self, profiles: list[dict]):
        self._by_key: dict[str, str] = {}
        self._by_number: dict[int, str] = {}
        for profile in profiles:
            supplier_id = clean(profile.get("supplier_id"))
            if supplier_id is None:
                continue
            for name in (supplier_id, profile.get("name"), profile.get("legal_name")):
                if clean(name):
                    self._by_key[name_key(name)] = supplier_id
            digits = re.sub(r"\D", "", supplier_id)
            if digits:
                self._by_number[int(digits)] = supplier_id

    def resolve(self, value) -> str | None:
        text = clean(value)
        if text is None:
            return None
        if text.isdigit():
            return self._by_number.get(int(text))
        found = self._by_key.get(name_key(text))
        if found:
            return found
        # Folder names: '<id>_<name>'
        head = text.split("_", 1)[0]
        return self._by_key.get(name_key(head)) if head != text else None

"""
Link rules and structural checks.

A rule joins two kinds of records on key columns (exact match). It can also say which records
must find a partner; those that don't become 'orphan' issues. Checks look at the linked graph
for problems a single join can't see, such as a delivery note shared across suppliers.
"""

from collections.abc import Callable
from dataclasses import dataclass

import pandas as pd

Predicate = Callable[[dict], bool]

ISSUE_COLUMNS = ["rule", "type", "record_id", "related", "detail"]
LINK_COLUMNS = ["src", "dst", "rule", "method", "key"]


def always(_: dict) -> bool:
    return True


def delivered(record: dict) -> bool:
    """PO line that says it was delivered (and is not a cancellation)."""
    attrs = record["attrs"]
    return bool(attrs.get("delivered_date")) and (attrs.get("quantity") or 0) > 0


def has_batch(record: dict) -> bool:
    return record["batch"] is not None


@dataclass(frozen=True)
class Rule:
    name: str
    src: str
    dst: str
    on: tuple[tuple[str, str], ...]  # (src column, dst column); list columns are exploded
    expect_src: Predicate | None = None  # src records that must link, else orphan
    src_orphan: str = ""
    expect_dst: Predicate | None = None
    dst_orphan: str = ""


def _part_rule(kind: str, column: str = "material_id") -> Rule:
    return Rule(
        f"{kind}_to_part", kind, "part", ((column, "material_id"),),
        expect_src=always, src_orphan="Material is not in the parts master",
    )


RULES: list[Rule] = [
    Rule(
        "receipt_to_po_line", "goods_receipt", "po_line",
        (("po_number", "po_number"), ("po_line", "po_line")),
        expect_src=always, src_orphan="Goods receipt without a matching PO line",
        expect_dst=delivered, dst_orphan="PO line marked delivered, but no goods receipt",
    ),
    Rule(
        "stock_to_receipt", "stock_batch", "goods_receipt", (("batch", "gr_number"),),
        expect_src=always, src_orphan="Stock batch without a goods receipt",
    ),
    Rule(
        "shipment_to_po_line", "shipment", "po_line",
        (("po_numbers", "po_number"), ("material_ids", "material_id")),
        expect_src=always, src_orphan="Shipment with no PO line for any of its materials",
    ),
    Rule(
        "shipment_to_tracker", "shipment", "tracker_row", (("shipment_id", "shipment_id"),),
        expect_src=always, src_orphan="Shipment missing from the Excel tracker",
        expect_dst=always, dst_orphan="Tracker row with no shipment in the ERP feed",
    ),
    _part_rule("po_line"),
    _part_rule("goods_receipt"),
    _part_rule("stock_batch"),
    _part_rule("shipment", "material_ids"),
]


def _key_frame(df: pd.DataFrame, columns: list[str]) -> pd.DataFrame:
    keys = [f"k{i}" for i in range(len(columns))]
    frame = df[["record_id", *columns]].copy()
    frame.columns = ["record_id", *keys]
    for key in keys:
        if frame[key].map(lambda v: isinstance(v, list)).any():
            frame = frame.explode(key)
    return frame.dropna(subset=keys).astype({k: str for k in keys})


def apply_rule(records: pd.DataFrame, rule: Rule) -> tuple[pd.DataFrame, list[dict], list[dict]]:
    """Return (links, issues, coverage rows) for one rule."""
    src = records[records.kind == rule.src]
    dst = records[records.kind == rule.dst]
    src_keys = _key_frame(src, [s for s, _ in rule.on])
    dst_keys = _key_frame(dst, [d for _, d in rule.on])
    keys = [c for c in src_keys.columns if c != "record_id"]
    merged = src_keys.merge(dst_keys, on=keys, suffixes=("_src", "_dst"))
    links = pd.DataFrame(
        {
            "src": merged["record_id_src"],
            "dst": merged["record_id_dst"],
            "rule": rule.name,
            "method": "exact",
            "key": merged[keys].astype(str).agg("/".join, axis=1) if len(merged) else [],
        },
        columns=LINK_COLUMNS,
    ).drop_duplicates(subset=["src", "dst"])

    issues, coverage = [], []
    for side, frame, predicate, message, linked in (
        ("src", src, rule.expect_src, rule.src_orphan, set(links.src)),
        ("dst", dst, rule.expect_dst, rule.dst_orphan, set(links.dst)),
    ):
        if predicate is None:
            continue
        expected = [r for r in frame.to_dict("records") if predicate(r)]
        missing = [r for r in expected if r["record_id"] not in linked]
        coverage.append({"rule": rule.name, "side": side, "kind": rule.src if side == "src" else rule.dst,
                         "expected": len(expected), "linked": len(expected) - len(missing)})
        issues += [
            {"rule": rule.name, "type": "orphan", "record_id": r["record_id"], "related": None,
             "detail": message}
            for r in missing
        ]
    return links, issues, coverage


# --- Structural checks -----------------------------------------------------------------------


def check_duplicate_records(records: pd.DataFrame, links: pd.DataFrame) -> list[dict]:
    dupes = records[records.record_id.duplicated(keep=False)]
    return [
        {"rule": "duplicate_record", "type": "conflict", "record_id": rid, "related": None,
         "detail": f"Same record in {len(group)} rows: {', '.join(sorted(set(group.source)))}"}
        for rid, group in dupes.groupby("record_id")
    ]


def check_delivery_note_suppliers(records: pd.DataFrame, links: pd.DataFrame) -> list[dict]:
    receipts = records[(records.kind == "goods_receipt") & records.delivery_note.notna()]
    issues = []
    for note, group in receipts.groupby("delivery_note"):
        suppliers = sorted(set(group.supplier_id.dropna()))
        if len(suppliers) > 1:
            issues += [
                {"rule": "delivery_note_suppliers", "type": "conflict", "record_id": rid,
                 "related": None, "detail": f"Delivery note {note} used by suppliers {', '.join(suppliers)}"}
                for rid in group.record_id
            ]
    return issues


def check_open_line_received(records: pd.DataFrame, links: pd.DataFrame) -> list[dict]:
    received = set(links[links.rule == "receipt_to_po_line"].dst)
    lines = records[(records.kind == "po_line") & records.record_id.isin(received)]
    return [
        {"rule": "open_line_received", "type": "conflict", "record_id": r["record_id"],
         "related": None, "detail": "PO line still open, but goods were received"}
        for r in lines.to_dict("records")
        if r["attrs"].get("status") == "open"
    ]


def check_shipment_pos_known(records: pd.DataFrame, links: pd.DataFrame) -> list[dict]:
    known = set(records[records.kind == "po_line"].po_number)
    issues = []
    for r in records[records.kind.isin(["shipment", "tracker_row"])].to_dict("records"):
        for po in r["po_numbers"] or []:
            if po not in known:
                issues.append({"rule": "shipment_po_known", "type": "orphan", "record_id": r["record_id"],
                               "related": None, "detail": f"References PO {po}, which is not in SAP"})
    return issues


def check_tracker_pos_match(records: pd.DataFrame, links: pd.DataFrame) -> list[dict]:
    by_id = records.drop_duplicates("record_id").set_index("record_id")  # dupes: own check
    issues = []
    for link in links[links.rule == "shipment_to_tracker"].itertuples():
        feed = set(by_id.at[link.src, "po_numbers"] or [])
        tracker = set(by_id.at[link.dst, "po_numbers"] or [])
        if feed != tracker:
            issues.append({"rule": "tracker_pos_match", "type": "conflict", "record_id": link.src,
                           "related": link.dst,
                           "detail": f"Feed lists POs {sorted(feed)}, tracker lists {sorted(tracker)}"})
    return issues


def check_unresolved_suppliers(records: pd.DataFrame, links: pd.DataFrame) -> list[dict]:
    return [
        {"rule": "unresolved_supplier", "type": "orphan", "record_id": r["record_id"], "related": None,
         "detail": f"Unknown supplier '{r['attrs']['supplier_raw']}'"}
        for r in records.to_dict("records")
        if r["attrs"].get("supplier_raw")
    ]


CHECKS = [
    check_duplicate_records,
    check_delivery_note_suppliers,
    check_open_line_received,
    check_shipment_pos_known,
    check_tracker_pos_match,
    check_unresolved_suppliers,
]


def apply_all(records: pd.DataFrame) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    all_links, issues, coverage = [], [], []
    for rule in RULES:
        links, rule_issues, rule_coverage = apply_rule(records, rule)
        all_links.append(links)
        issues += rule_issues
        coverage += rule_coverage
    links = pd.concat(all_links, ignore_index=True) if all_links else pd.DataFrame(columns=LINK_COLUMNS)
    for check in CHECKS:
        issues += check(records, links)
    return links, pd.DataFrame(issues, columns=ISSUE_COLUMNS), pd.DataFrame(coverage)

