    )
    issues = build(portal).issues
    agreement = issues[issues.rule == "link_agreement"]
    assert set(agreement.record_id) == {"goods_receipt:7000000006"}
    assert {d.split(" ")[0] for d in agreement.detail} == {"supplier_id", "material_id"}


