    versions = graph.records[graph.records.entity == "supplier:SUP-0007"]
    assert set(versions.record_id) == {CSV_VERSION, JSON_VERSION}  # neither silently wins
    assert (CSV_VERSION, JSON_VERSION) in links_of(graph, "same_entity")
