import json, glob, os, re, collections
import pandas as pd
C = collections.Counter
docs = []
for d in glob.glob("data/store/image_recognizer/*/"):
    m = json.load(open(d + "meta.json"))
    if m["status"] == "ok" and os.path.exists(d + "verdict.json"):
        docs.append((m, json.load(open(d + "verdict.json"))))
gr = pd.read_csv("data/portal/soony/erp/goods_receipts.csv", dtype=str)
po = pd.read_csv("data/portal/soony/erp/purchase_orders_2025H2-2026.csv", dtype=str)

def num(x):
    """Raw-text number: a dot or comma followed by exactly 3 digits is a thousands separator."""
    raw = x["value"].replace(" ", " ")
    m = re.search(r"\d[\d., ]*", raw)
    if not m: return x["number"]
    s = m.group(0).strip().replace(" ", "")
    if re.fullmatch(r"\d{1,3}([.,]\d{3})+", s): return float(re.sub(r"[.,]", "", s))
    return x["number"]

misread = 0
print("== Delivery notes vs SAP receipts (by sets of quantities)")
dn_mism = []
for m, v in docs:
    if v["document_type"] != "delivery_note": continue
    dn = os.path.basename(m["path"]).split("_", 1)[1].rsplit(".", 1)[0]
    rows = gr[gr.delivery_note == dn]
    if rows.empty: dn_mism.append((dn, "no receipt in SAP", None)); continue
    paper = sorted(num(x) for l in v["lines"] for x in l["values"]
                   if x["field"] in ("quantity_delivered", "quantity_shipped") and not x["crossed_out"] and num(x) is not None)
    misread += sum(1 for l in v["lines"] for x in l["values"] if x["field"].startswith("quantity") and x["number"] is not None and num(x) != x["number"])
    sap = sorted(float(q) for q in rows.qty_received)
    if paper != sap: dn_mism.append((dn, paper, sap))
for x in dn_mism: print("  ", x)
print("  number misreads (dot/comma thousands) fixed from raw text:", misread)

print("== Confirmations vs PO")
diff = C(); ex = collections.defaultdict(list)
for m, v in docs:
    if v["document_type"] != "order_confirmation": continue
    ponum = os.path.basename(m["path"]).rsplit("_", 1)[1].rsplit(".", 1)[0]
    lines = po[po.po_number == ponum]
    sup = m["path"].split("/")[1][:16]
    for l in v["lines"]:
        r = lines[lines.material_id == l["material_id"]]
        if r.empty: 
            if l["material_id"]: diff[(sup, "line not in SAP")] += 1; ex[(sup, "line not in SAP")].append(f"{ponum} {l['material_id']}")
            continue
        f = {}
        for x in l["values"]:
            if not x["crossed_out"]: f.setdefault(x["field"], (num(x), x["value"]))
        q = f.get("quantity_confirmed") or f.get("quantity_ordered")
        if q and q[0] is not None and all(abs(float(s) - q[0]) > 0.5 for s in r.quantity):
            diff[(sup, "quantity")] += 1; ex[(sup, "quantity")].append(f"{ponum} {l['material_id']} paper {q[0]} SAP {list(r.quantity)}")
        p = f.get("unit_price")
        if p and p[1] and all(abs(float(s) - float(re.sub(r'[^0-9.]', '', p[1].replace(',', '.')) or 0)) > 1e-6 for s in r.unit_price):
            diff[(sup, "price")] += 1; ex[(sup, "price")].append(f"{ponum} paper {p[1]} SAP {list(r.unit_price)}")
        dc = f.get("date_confirmed")
        if dc and dc[1]:
            iso = dc[1]
            mm = re.match(r"(\d{4})-(\d{2})-(\d{2})", iso) or None
            if mm and all(iso[:10] != (s or "") for s in r.promised_date):
                diff[(sup, "date")] += 1; ex[(sup, "date")].append(f"{ponum} paper {iso} SAP {list(r.promised_date)}")
for k, n in diff.most_common(): print("  ", n, k, ex[k][:2])

print("== Statement topics (confirmations)")
print("  ", C(s["topic"] for m, v in docs if v["document_type"] == "order_confirmation" for s in v["statements"]).most_common())
st = C()
for m, v in docs:
    if v["document_type"] != "order_confirmation": continue
    sup = m["path"].split("/")[1][:16]
    for s in v["statements"]:
        if s["topic"] in ("revision", "approval_status", "terms", "price"):
            st[(sup, s["topic"], s["text_en"][:70])] += 1
for k, n in st.most_common(12): print("  ", n, k)
print("== Real corrections (a value changed)")
for m, v in docs:
    for c in v["corrections"]:
        if c["original"]: print("  ", m["path"].split("/")[-1], c["original"], "->", c["replacement"])
print("== Handwritten remarks/notes")
for m, v in docs:
    for c in v["corrections"]:
        if not c["original"] and c["replacement"] and not re.fullmatch(r"[A-Z][a-z]+ [A-Z]\.", c["replacement"].strip()) and "RECEIVED" not in c["replacement"] and "LTD" not in c["replacement"]:
            print("  ", m["path"].split("/")[-1], "|", c["replacement"][:80])
