    return results


def _label(check: dict) -> str:
    return ", ".join(f"{k}={v}" for k, v in check.items())


def report(results: list[CaseResult]) -> tuple[str, bool]:
    """Readable table, and whether every must-catch case passed."""
    rows, trusted = [], True
    for r in results:
